  pharmacyMedicineTotalMinor: integer("pharmacy_medicine_total_minor").notNull().default(0),
  medicineCommissionMinor: integer("medicine_commission_minor").notNull().default(0),
  patientMedicineTotalMinor: integer("patient_medicine_total_minor").notNull().default(0),
  deliveryFeeMinor: integer("delivery_fee_minor").notNull().default(0),
  courierPayoutMinor: integer("courier_payout_minor").notNull().default(0),
  deliveryCommissionMinor: integer("delivery_commission_minor").notNull().default(0),
  // Optional: reference to a prescription that was reviewed for this order.
  prescriptionId: uuid("prescription_id"),
  // ── Dispatch fields (HQ-driven, delivery path) ──────────────────────────────
