// src/lib/push.ts
var EXPO_PUSH_URL = "https://exp.host/--/api/v2/push/send";
function isExpoPushToken(token) {
  return /^(ExponentPushToken|ExpoPushToken)\[.+\]$/.test(token);
}
async function sendExpoPush(message, options) {
  if (!isExpoPushToken(message.to)) {
    console.warn("[push] Skipping invalid Expo push token");
    return false;
  }
  try {
    const res = await fetch(EXPO_PUSH_URL, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Accept: "application/json"
      },
      body: JSON.stringify([
        {
          to: message.to,
          title: message.title,
          body: message.body,
          data: message.data ?? {},
          sound: "default",
          priority: "high"
        }
      ])
    });
    if (!res.ok) {
      console.error(`[push] Expo push API returned ${res.status}`);
      return false;
    }
    const json3 = await res.json();
    const ticket = json3.data?.[0];
    if (ticket && ticket.status !== "ok") {
      console.error(
        `[push] Push ticket error: ${ticket.details?.error ?? ""} ${ticket.message ?? ""}`
      );
      if (ticket.details?.error === "DeviceNotRegistered") {
        try {
          await options?.onDeviceNotRegistered?.();
        } catch (err) {
          console.error("[push] Failed to clear unregistered device token:", err);
        }
      }
      return false;
    }
    return true;
  } catch (err) {
    console.error("[push] Expo push send failed:", err);
    return false;
  }
}

// src/lib/patientNotifications.ts
async function createPatientNotification(payload) {
  try {
    await db.insert(patientNotificationsTable).values({
      patientId: payload.patientId,
      title: payload.title,
      body: payload.body,
      type: payload.type ?? null,
      referenceId: payload.referenceId ?? null
    });
  } catch (err) {
    console.error("[patientNotifications] DB insert failed:", err);
  }
  try {
    await sendSms2(payload.patientPhone, `MobiCare: ${payload.body}`);
  } catch (err) {
    const code = err instanceof Error && "code" in err ? String(err.code) : "SMS_UNKNOWN_ERROR";
    console.error("[patientNotifications] SMS send failed", { code });
  }
  try {
    const [patient2] = await db.select({ expoPushToken: patientsTable.expoPushToken }).from(patientsTable).where(eq(patientsTable.id, payload.patientId)).limit(1);
    const expoPushToken = patient2?.expoPushToken;
    if (expoPushToken) {
      await sendExpoPush({
        to: expoPushToken,
        title: payload.title,
        body: payload.body,
        data: payload.referenceId ? { url: `/order/${payload.referenceId}` } : {}
      }, {
        onDeviceNotRegistered: async () => {
          await db.update(patientsTable).set({ expoPushToken: null, updatedAt: /* @__PURE__ */ new Date() }).where(
            and(
              eq(patientsTable.id, payload.patientId),
              eq(patientsTable.expoPushToken, expoPushToken)
            )
          );
        }
      });
    }
  } catch (err) {
    console.error("[patientNotifications] Push send failed:", err);
  }
}
function notificationForStatus(status, fulfillmentType) {
  switch (status) {
    case "confirmed":
      return {
        title: "Order confirmed \u2713",
        body: "The pharmacy has confirmed your order and will start preparing it shortly.",
        type: "order_status"
      };
    case "packaging":
      return {
        title: "Order being prepared \u{1F4E6}",
        body: "Your medicines are being packed and will be ready soon.",
        type: "order_status"
      };
    case "ready":
      return fulfillmentType === "delivery" ? {
        title: "Ready for dispatch \u{1F6B4}",
        body: "Your order is packed and waiting for a rider. We'll notify you when it's picked up.",
        type: "order_status"
      } : {
        title: "Ready for collection \u{1F3E5}",
        body: "Your order is ready! Please bring your ID to the pharmacy to collect it.",
        type: "order_status"
      };
    case "assigned":
      return {
        title: "Rider assigned \u{1F6B4}",
        body: "A courier has been assigned and is heading to the pharmacy to collect your order.",
        type: "order_status"
      };
    case "picked_up":
      return {
        title: "Order collected by courier \u{1F4EC}",
        body: "The pharmacy has handed your order to the assigned courier. HQ will mark it as delivering when the journey begins.",
        type: "order_status"
      };
    case "delivering":
      return {
        title: "On the way! \u{1F6F5}",
        body: "Your rider is heading to your delivery address. Please be available to receive it.",
        type: "order_status"
      };
    case "delivered":
      return {
        title: "Delivered! \u{1F389}",
        body: "Your order has been delivered. Thank you for choosing MobiCare \u2014 get well soon!",
        type: "order_status"
      };
    case "collected":
      return {
        title: "Order collected \u2705",
        body: "Your order has been collected in person. Thank you for choosing MobiCare!",
        type: "order_status"
      };
    case "cancelled":
      return {
        title: "Order cancelled",
        body: "Your order has been cancelled. If you have questions, please contact the pharmacy.",
        type: "order_cancelled"
      };
    default:
      return null;
  }
}

