async function hydrateOrders(orders) {
  const orderIds = orders.map((o) => o.id);
  const pharmacyIds = [...new Set(orders.map((o) => o.pharmacyId))];
  const courierIds = [
    ...new Set(orders.map((o) => o.courierId).filter((c) => !!c))
  ];
  const [items, pharmacies, couriers] = await Promise.all([
    orderIds.length ? db.select().from(orderItemsTable).where(inArray(orderItemsTable.orderId, orderIds)) : Promise.resolve([]),
    pharmacyIds.length ? db.select({ id: pharmaciesTable.id, name: pharmaciesTable.name }).from(pharmaciesTable).where(inArray(pharmaciesTable.id, pharmacyIds)) : Promise.resolve([]),
    courierIds.length ? db.select({
      id: couriersTable.id,
      name: couriersTable.name,
      phone: couriersTable.phone,
      photoPath: couriersTable.photoPath
    }).from(couriersTable).where(inArray(couriersTable.id, courierIds)) : Promise.resolve([])
  ]);
  const itemsByOrder = {};
  for (const item of items) {
    (itemsByOrder[item.orderId] ??= []).push(item);
  }
  const pharmacyById = Object.fromEntries(
    pharmacies.map((p2) => [p2.id, p2.name])
  );
  const courierById = Object.fromEntries(couriers.map((c) => [c.id, c]));
  return orders.map((o) => ({
    ...o,
    items: itemsByOrder[o.id] ?? [],
    pharmacyName: pharmacyById[o.pharmacyId] ?? null,
    courier: o.courierId ? (() => {
      const courier = courierById[o.courierId];
      return courier ? { id: courier.id, name: courier.name, phone: courier.phone, photoUrl: courier.photoPath ? `/api/couriers/${courier.id}/photo` : null } : null;
    })() : null
  }));
}
