function decimalLeonesToMinor(value) {
  const text2 = String(value).trim();
  const match = /^(\d+)(?:\.(\d{1,2}))?$/.exec(text2);
  if (!match) throw new Error(`Invalid Leone amount: ${text2}`);
  const amount = Number(match[1]) * 100 + Number((match[2] ?? "").padEnd(2, "0"));
  if (!Number.isSafeInteger(amount)) throw new Error("Leone amount exceeds safe range");
  return amount;
}
function minorToLeones(value) {
  if (!Number.isSafeInteger(value) || value < 0) {
    throw new Error("Invalid minor-unit amount");
  }
  return `${Math.floor(value / 100)}.${String(value % 100).padStart(2, "0")}`;
}

// src/lib/financialAllocation.ts
var SERVICE_FEE_BASIS_POINTS = 500;
function calculateOrderPricing(drugSubtotalMinor) {
  if (!Number.isSafeInteger(drugSubtotalMinor) || drugSubtotalMinor < 0) {
    throw new Error("drugSubtotalMinor must be a non-negative safe integer");
  }
  const serviceFeeMinor = Math.round(
    drugSubtotalMinor * SERVICE_FEE_BASIS_POINTS / 1e4
  );
  return {
    drugSubtotalMinor,
    serviceFeeMinor,
    totalPaidMinor: drugSubtotalMinor + serviceFeeMinor
  };
}

